JUDITH_BLOCKED = {
    "Monday": [(12 * 60, 12 * 60 + 30)],
    "Tuesday": [],
    "Wednesday": [(11 * 60 + 30, 12 * 60)],
}

TIMOTHY_BLOCKED = {
    "Monday": [
        (9 * 60 + 30, 10 * 60),
        (10 * 60 + 30, 11 * 60 + 30),
        (12 * 60 + 30, 14 * 60),
        (15 * 60 + 30, 17 * 60),
    ],
