        (14 * 60 + 30, 17 * 60),
    ],
    "Wednesday": [
        (9 * 60, 9 * 60 + 30),
        (10 * 60 + 30, 11 * 60),
        (13 * 60 + 30, 14 * 60 + 30),
        (15 * 60, 15 * 60 + 30),
        (16 * 60, 16 * 60 + 30),
    ],
}

def overlaps(start, end, blocks):
    for block_start, block_end in blocks:
        if start < block_end and end > block_start:
            return True
    return False

def is_available(day, start):
    end = start + DURATION
    if start < WORK_START or end > WORK_END:
        return False
    if overlaps(start, end, JUDITH_BLOCKED[day]):
        return False
    if overlaps(start, end, TIMOTHY_BLOCKED[day]):
        return False
    return True

def preference_score(day, start):
    score = 0
    if day == "Monday":
        score -= 10
    if day == "Wednesday" and start < 12 * 60:
        score += 10
    return score

def format_time(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"

best_day = None
best_start = None
best_score = None

for day in DAYS:
    for start in range(WORK_START, WORK_END - DURATION + 1):
        if not is_available(day, start):
            continue
        score = preference_score(day, start)
        if best_score is None or score > best_score:
            best_score = score
            best_day = day
            best_start = start

print([best_day, format_time(best_start), format_time(best_start + DURATION)])
